  about: `Bastar is a culturally rich district in the southern part of
  Chhattisgarh. The district headquarters is Jagdalpur, which is also
  the headquarters of Bastar division. Bastar is known for its dense
  forests, waterfalls, caves, tribal culture, handicrafts, traditional
  festivals and natural beauty. Chitrakote Waterfall, Tirathgarh
  Waterfall, Kanger Valley National Park, Kutumsar Cave, Kailash Cave,
  Bastar Palace and Dalpat Sagar are among the major attractions of
  the district. Jagdalpur is an important cultural and handicraft
  centre of the region.`,

