  about: `Bemetara is a district in the central part of Chhattisgarh.
  The district was formed on 1 January 2012 after being separated
  from Durg district. Bemetara is known for agriculture, especially
  pulses and oilseed crops. The district has a predominantly rural
  landscape with fertile agricultural land, traditional culture,
  temples and several important religious and historical places.
  Bhadrakali Temple at Bemetara and Sita Devi Temple at Devarbija
  are among the major tourist attractions of the district.`,

