  about: `Bijapur is a district in the southern part of Chhattisgarh.
  The district headquarters is Bijapur town. The district came into
  existence on 1 May 2007 after being separated from Dantewada district.
  Bijapur is known for its dense forests, hills, tribal culture,
  rivers, wildlife and natural beauty. Important attractions include
  Indravati National Park, Bhairamgarh Wildlife Sanctuary, Bhadrakali
  Temple, Bhairamdev Temple and Sakal Narayan Cave.`,

