  about: `Bilaspur is one of the major districts of Chhattisgarh and
  is popularly known as the Nyayadhani (Judicial Capital) of the state.
  The district headquarters is Bilaspur city. The High Court of
  Chhattisgarh is located at Bodri in Bilaspur district. The district
  is known for its historical places, temples, educational institutions,
  railway connectivity, the Arpa River and attractions such as Kanan
  Pendari, Ratanpur, Malhar and Tala.`,

