  about: `Gariaband district was formed on 1 January 2012 after being carved out of Raipur district. The district headquarters is Gariaband town. The district is known for its natural resources, forests, rivers, religious places and scenic tourist destinations. Pairi and Sondhur rivers flow through the district and meet at Rajim, forming the famous Triveni Sangam. Rajim is an important religious and cultural centre of Chhattisgarh.`,

