  about: `Jashpur district is situated in the north-eastern corner of Chhattisgarh and shares its borders with Jharkhand and Odisha. Jashpur Nagar is the district headquarters. The district is known for its forests, tribal culture, waterfalls, caves, churches, rivers and scenic natural beauty. Jashpur is also known for its rich cultural heritage and biodiversity.`,

