  about: `Kabirdham, also known as Kawardha, is a district of Chhattisgarh situated on the southern bank of the Sakri River. The district is known for its rich historical, archaeological, religious and natural heritage. Bhoramdev Temple, Chilphi Valley, Bhoramdev Wildlife Sanctuary, Pachrahi, Saroda Dam and Rani Dahar Waterfall are among the important attractions of the district. Bhoramdev was historically associated with the Nagavanshi rulers and is one of the major heritage sites of Chhattisgarh.`,

