  about: `Rajnandgaon is a culturally rich city and 
    district headquarters in western Chhattisgarh. 
    Known as “Sanskardhani”, it has a strong history, 
    rich literary heritage, agriculture and religious 
    significance. The district is famous for attractions 
    like Maa Bamleshwari Temple in Dongargarh, Barfani Dham,
    Pragyagiri and Mangata Wildlife Park. Rajnandgaon is also
    known for its hockey tradition, folk culture, festivals 
    and well-connected road and railway network.`,

