// ==========================================
// CREATE NON-ENUMERABLE ALIASES
// ==========================================

Object.entries(districtAliases).forEach(
  ([alias, canonicalName]) => {

    if (districtData[canonicalName]) {
      Object.defineProperty(
        districtData,
        alias,
        {
          value: districtData[canonicalName],
          enumerable: false,
          configurable: true,
          writable: false
        }
      );
    }

  }
);

export default districtData;